<?php if($recordedPayments): ?><div class="order-payment-details"><h3>Pagos registrados</h3><?php foreach($recordedPayments as $recorded): $paymentDetails=json_decode($recorded['details']??'null',true)?:[]; ?><dl><dt>ID del pago</dt><dd><?= e($recorded['id']) ?></dd><dt>Estado confirmado</dt><dd><?= e(paymentLabel($recorded['status'])) ?></dd><dt>Importe</dt><dd><?= money($recorded['amount_cents']) ?> ARS</dd><?php foreach(['payment_type_id'=>'Tipo de pago','payment_method_id'=>'Medio de pago','merchant_order_id'=>'Orden comercial','date_approved'=>'Fecha de aprobación'] as $key=>$label): if(!empty($paymentDetails[$key])): ?><dt><?= e($label) ?></dt><dd><?= e($paymentDetails[$key]) ?></dd><?php endif; endforeach ?></dl><?php endforeach ?></div><?php endif ?>
<?php if($returnHint && !array_filter($recordedPayments,fn($p)=>(string)$p['id']===(string)($returnHint['payment_id']??''))): ?><div class="order-payment-details"><h3>Referencia recibida</h3><p class="microcopy">Datos del regreso de Mercado Pago, todavía sin verificar. El estado del pedido se confirma con la notificación del pago.</p><dl><?php foreach(['payment_id'=>'ID del pago','status'=>'Estado informado al regresar','payment_type'=>'Tipo de pago','merchant_order_id'=>'Orden comercial','external_reference'=>'Referencia de compra','preference_id'=>'Preferencia','site_id'=>'Sitio','processing_mode'=>'Procesamiento'] as $key=>$label): if(!empty($returnHint[$key])): ?><dt><?= e($label) ?></dt><dd><?= e($key==='status'?paymentLabel($returnHint[$key]):$returnHint[$key]) ?></dd><?php endif; endforeach ?></dl></div><?php endif ?>
<?php if(!empty($order['preference_id']) && $recordedPayments): ?><p class="microcopy payment-reference">Preferencia: <?= e($order['preference_id']) ?><br>Referencia de compra: <?= (int)$order['id'] ?></p><?php endif ?>
